// ---------------------------------------------------------------- strings

#define PATHLEN 600
static unsigned slen(const char *s) { unsigned n = 0; while (s[n]) n++; return n; }
static void scpy(char *d, unsigned cap, const char *s) { unsigned i = 0; while (s[i] && i + 1 < cap) { d[i] = s[i]; i++; } d[i] = 0; }
static void cat(char *d, unsigned cap, const char *s) { unsigned n = slen(d); if (n < cap) scpy(d + n, cap - n, s); }
static char low(char c) { return c >= 'A' && c <= 'Z' ? c + 32 : c; }
static int sameText(const char *a, const char *b) { while (*a && low(*a) == low(*b)) a++, b++; return !*a && !*b; }
static int sameTextN(const char *a, const char *b, unsigned n) { for (unsigned i = 0; i < n; i++) if (low(a[i]) != low(b[i]) || !a[i]) return 0; return 1; }
static int contains(const char *hay, unsigned n, const char *needle) {
    unsigned m = slen(needle);
    for (unsigned i = 0; i + m <= n; i++) { unsigned j = 0; while (j < m && hay[i + j] == needle[j]) j++; if (j == m) return 1; }
    return 0;
}
static void join(char *out, const char *dir, const char *name) { scpy(out, PATHLEN, dir); cat(out, PATHLEN, "\\"); cat(out, PATHLEN, name); }

// ---------------------------------------------------------------- files

static int exists(const char *p) { return GetFileAttributesA(p) != 0xFFFFFFFF; }
static char *readAll(const char *p, DWORD *n) {
    HANDLE f = CreateFileA(p, 0x80000000 /*GENERIC_READ*/, 1 | 2 /*share read/write*/, 0, 3 /*OPEN_EXISTING*/, 0x80, 0);
    if (f == (HANDLE)-1) return 0;
    DWORD size = GetFileSize(f, 0), got = 0;
    char *b = HeapAlloc(GetProcessHeap(), 0, (U64)size + 1);
    if (b && (!ReadFile(f, b, size, &got, 0) || got != size)) { HeapFree(GetProcessHeap(), 0, b); b = 0; }
    CloseHandle(f);
    if (b) { b[size] = 0; *n = size; }
    return b;
}
static int writeAll(const char *p, const void *d, DWORD n) {
    HANDLE f = CreateFileA(p, 0x40000000 /*GENERIC_WRITE*/, 0, 0, 2 /*CREATE_ALWAYS*/, 0x80, 0);
    if (f == (HANDLE)-1) return 0;
    DWORD put = 0; BOOL ok = WriteFile(f, d, n, &put, 0) && put == n;
    CloseHandle(f);
    return ok;
}
static int sameAs(const char *p, const BYTE *d, DWORD n) {
    DWORD got; char *b = readAll(p, &got); if (!b) return 0;
    int same = got == n; for (DWORD i = 0; same && i < n; i++) if ((BYTE)b[i] != d[i]) same = 0;
    HeapFree(GetProcessHeap(), 0, b);
    return same;
}
static int isOurDll(const char *p) {
    DWORD n; char *b = readAll(p, &n); if (!b) return 0;
    int ours = contains(b, n, "Controller mod loaded") || contains(b, n, "WASD mod loaded");
    HeapFree(GetProcessHeap(), 0, b);
    return ours;
}
// Marks a file as just changed: the mod reads the newest of default.txt and the
// saved layouts, so a saved layout stays in charge after an update.
static void touch(const char *p) {
    HANDLE f = CreateFileA(p, 0x100 /*FILE_WRITE_ATTRIBUTES*/, 1 | 2, 0, 3, 0x80, 0);
    if (f == (HANDLE)-1) return;
    DWORD now[2]; GetSystemTimeAsFileTime(now); SetFileTime(f, 0, 0, now);
    CloseHandle(f);
}
static int newer(const char *a, const char *b);
static void activeSettings(const char *dir, char *out);
// Files matching `name`: finds the newest; with `each`, calls it for every one.
static int findFiles(const char *dir, const char *name, char *newest, void (*each)(const char *, const char *)) {
    char pattern[PATHLEN]; join(pattern, dir, name);
    FINDDATA f; HANDLE h = FindFirstFileA(pattern, &f);
    if (h == (HANDLE)-1) return 0;
    DWORD best[2] = {0, 0}; int found = 0;
    do {
        if (f.attributes & 0x10) continue;
        char p[PATHLEN]; join(p, dir, f.name);
        if (each) each(p, f.name);
        if (!found || f.written[1] > best[1] || (f.written[1] == best[1] && f.written[0] > best[0])) {
            best[0] = f.written[0]; best[1] = f.written[1]; found = 1;
            if (newest) scpy(newest, PATHLEN, p);
        }
    } while (FindNextFileA(h, &f));
    FindClose(h);
    return found;
}
// Saved key layouts: author.txt and the editor's wasdmod-MMDDYY.txt files.
static int findLayouts(const char *dir, char *newest, void (*each)(const char *, const char *)) {
    char a[PATHLEN], b[PATHLEN];
    int hasA = findFiles(dir, "author.txt", a, each), hasB = findFiles(dir, "wasdmod*.txt", b, each);
    if (newest && (hasA || hasB)) scpy(newest, PATHLEN, hasA && (!hasB || newer(a, b)) ? a : b);
    return hasA || hasB;
}
static const char *baseName(const char *p) { const char *b = p; for (; *p; p++) if (*p == '\\' || *p == '/') b = p + 1; return b; }
static void deleteFile(const char *p, const char *name) { (void)name; DeleteFileA(p); }
// Older versions named everything wasd-mod...: a saved layout keeps its date
// (wasd-mod-093026.txt -> wasdmod-093026.txt) and its time stamp.
static char migrateDir[PATHLEN];
static void renameLegacy(const char *p, const char *name) {
    char to[PATHLEN]; join(to, migrateDir, "wasdmod"); cat(to, PATHLEN, name + 8);
    MoveFileExA(p, to, 1 /*MOVEFILE_REPLACE_EXISTING*/);
}

static int newer(const char *a, const char *b) { // a changed after b
    FILEINFO x, y;
    if (!GetFileAttributesExA(a, 0, &x)) return 0;
    if (!GetFileAttributesExA(b, 0, &y)) return 1;
    return x.written[1] > y.written[1] || (x.written[1] == y.written[1] && x.written[0] > y.written[0]);
}

static int gameRunning(void) {
    HANDLE s = CreateToolhelp32Snapshot(2 /*TH32CS_SNAPPROCESS*/, 0);
    if (s == (HANDLE)-1) return 0;
    PROCESSENTRY e; memset(&e, 0, sizeof(e)); e.size = sizeof(e);
    int found = 0;
    for (BOOL ok = Process32First(s, &e); ok && !found; ok = Process32Next(s, &e)) if (sameText(e.exe, "Dungeons-Win64-Shipping.exe")) found = 1;
    CloseHandle(s);
    return found;
}

// ---------------------------------------------------------------- finding the game

static const char *GAME_SUB = "steamapps\\common\\Minecraft Dungeons II\\Dungeons\\Binaries\\Win64";
static int isGameDir(const char *dir) { char p[PATHLEN]; join(p, dir, "Dungeons-Win64-Shipping.exe"); return exists(p); }

static int tryLibrary(const char *lib, char *out) {
    char dir[PATHLEN]; join(dir, lib, GAME_SUB);
    if (!isGameDir(dir)) return 0;
    scpy(out, PATHLEN, dir);
    return 1;
}
static int regString(HANDLE root, const char *key, const char *value, char *out, DWORD cap) {
    HANDLE k; if (RegOpenKeyExA(root, key, 0, 0x20019 /*KEY_READ*/, &k)) return 0;
    DWORD type = 0, size = cap - 1; LONG r = RegQueryValueExA(k, value, 0, &type, (BYTE *)out, &size);
    RegCloseKey(k);
    if (r || (type != 1 && type != 2)) return 0;
    out[size < cap ? size : cap - 1] = 0;
    for (char *c = out; *c; c++) if (*c == '/') *c = '\\';
    unsigned n = slen(out); while (n && out[n - 1] == '\\') out[--n] = 0;
    return out[0] != 0;
}
// Steam's library list: every "path" "D:\\SteamLibrary" entry in libraryfolders.vdf.
static int searchLibraries(const char *steam, char *out) {
    if (tryLibrary(steam, out)) return 1;
    char p[PATHLEN]; join(p, steam, "steamapps\\libraryfolders.vdf");
    DWORD n; char *b = readAll(p, &n); if (!b) return 0;
    int found = 0;
    for (DWORD i = 0; i + 6 < n && !found; i++) {
        if (b[i] != '"' || low(b[i + 1]) != 'p' || low(b[i + 2]) != 'a' || low(b[i + 3]) != 't' || low(b[i + 4]) != 'h' || b[i + 5] != '"') continue;
        DWORD j = i + 6; while (j < n && b[j] != '"' && b[j] != '\n') j++;
        if (j >= n || b[j] != '"') continue;
        char lib[PATHLEN]; unsigned k = 0; j++;
        while (j < n && b[j] != '"' && k + 1 < sizeof(lib)) {
            if (b[j] == '\\' && j + 1 < n && b[j + 1] == '\\') j++; // "D:\\SteamLibrary"
            lib[k++] = b[j] == '/' ? '\\' : b[j];
            j++;
        }
        lib[k] = 0;
        found = tryLibrary(lib, out);
    }
    HeapFree(GetProcessHeap(), 0, b);
    return found;
}
static int findGame(char *out) {
    char steam[PATHLEN];
    if (regString((HANDLE)0x80000001 /*HKCU*/, "Software\\Valve\\Steam", "SteamPath", steam, sizeof(steam)) && searchLibraries(steam, out)) return 1;
    if (regString((HANDLE)0x80000002 /*HKLM*/, "SOFTWARE\\WOW6432Node\\Valve\\Steam", "InstallPath", steam, sizeof(steam)) && searchLibraries(steam, out)) return 1;
    if (regString((HANDLE)0x80000002, "SOFTWARE\\Valve\\Steam", "InstallPath", steam, sizeof(steam)) && searchLibraries(steam, out)) return 1;
    const char *guesses[] = {"C:\\Program Files (x86)\\Steam", "C:\\Program Files\\Steam", "D:\\SteamLibrary", "D:\\Steam", "E:\\SteamLibrary"};
    for (unsigned i = 0; i < sizeof(guesses) / sizeof(*guesses); i++) if (tryLibrary(guesses[i], out)) return 1;
    // Bought from Minecraft.net (Minecraft Launcher) or the Xbox app: X:\XboxGames on
    // any local drive (removable ones are skipped: an empty card reader asks for a disk).
    DWORD drives = GetLogicalDrives();
    for (int d = 2; d < 26; d++) {
        if (!(drives >> d & 1)) continue;
        char root[4] = {(char)('A' + d), ':', '\\', 0};
        if (GetDriveTypeA(root) != 3 /*DRIVE_FIXED*/) continue;
        char dir[PATHLEN]; scpy(dir, PATHLEN, root); cat(dir, PATHLEN, "XboxGames\\Minecraft Dungeons II\\Content\\Dungeons\\Binaries\\Win64");
        if (isGameDir(dir)) { scpy(out, PATHLEN, dir); return 1; }
    }
    return 0;
}
// A file the player picked: the game's exe in Win64, or Dungeons.exe at the top.
static int dirFromPick(const char *file, char *out) {
    scpy(out, PATHLEN, file);
    unsigned n = slen(out); while (n && out[n - 1] != '\\' && out[n - 1] != '/') n--;
    if (n) n--;
    out[n] = 0;
    if (isGameDir(out)) return 1;
    cat(out, PATHLEN, "\\Dungeons\\Binaries\\Win64");
    return isGameDir(out);
}

// ---------------------------------------------------------------- install / uninstall

// Writes a built-in layout (default.txt, author.txt), which makes it the newest
// file and so the one the mod uses; an edited copy is kept as NAME.bak.
static int putLayout(const char *dir, const char *name, const BYTE *d, DWORD n) {
    char p[PATHLEN], bak[PATHLEN]; join(p, dir, name);
    if (exists(p) && !sameAs(p, d, n)) { scpy(bak, PATHLEN, p); cat(bak, PATHLEN, ".bak"); CopyFileA(p, bak, 0); }
    return writeAll(p, d, n);
}

enum { OK, ERR_RUNNING, ERR_OTHER_DLL, ERR_WRITE };
static const char *errorText[] = {
    "",
    "Minecraft Dungeons II is running. Close it, then try again.",
    "The game folder already has a different xinput1_4.dll (another mod?).",
    "Couldn't write to the game folder. Try running this installer as administrator.",
};

static int install(const char *dir, int replaceOther) {
    if (gameRunning()) return ERR_RUNNING;
    char dll[PATHLEN], ini[PATHLEN], txt[PATHLEN], editor[PATHLEN], p[PATHLEN];
    join(dll, dir, "xinput1_4.dll"); join(ini, dir, "default.txt"); join(editor, dir, "Key Layout Editor.html");
    if (exists(dll) && !isOurDll(dll)) {
        if (!replaceOther) return ERR_OTHER_DLL;
        join(p, dir, "xinput1_4.dll.other");
        if (!CopyFileA(dll, p, 0)) return ERR_WRITE;
    }
    if (!writeAll(dll, payloadDll, sizeof(payloadDll))) return ERR_WRITE;
    join(p, dir, "xinput1_4.dll.off"); if (exists(p) && isOurDll(p)) DeleteFileA(p); // installing turns it back on
    scpy(migrateDir, PATHLEN, dir); findFiles(dir, "wasd-mod*.txt", 0, renameLegacy);
    // The settings file used to be wasd-mod.ini, then wasdmod.ini; edited ones are kept as default.txt.bak.
    const char *oldIni[] = {"wasd-mod.ini", "wasdmod.ini"};
    for (unsigned i = 0; i < 2; i++) {
        join(p, dir, oldIni[i]);
        if (exists(p)) { char bak[PATHLEN]; join(bak, dir, "default.txt.bak"); if (!sameAs(p, payloadIni, sizeof(payloadIni))) CopyFileA(p, bak, 0); DeleteFileA(p); }
    }
    join(p, dir, "wasd-mod.log"); DeleteFileA(p);
    activeSettings(dir, txt); // the layout in use before the update
    if (!putLayout(dir, "default.txt", payloadIni, sizeof(payloadIni))) return ERR_WRITE;
    writeAll(editor, payloadEditor, sizeof(payloadEditor));
    // It stays in use: a saved layout is marked newer than the fresh default.txt. (Not
    // the newest saved one: a player who picked Default stays on Default.)
    if (!sameText(baseName(txt), "default.txt") && exists(txt)) touch(txt);
    return OK;
}

static int uninstall(const char *dir, int removeLayout) {
    if (gameRunning()) return ERR_RUNNING;
    char p[PATHLEN];
    join(p, dir, "xinput1_4.dll"); if (exists(p) && isOurDll(p) && !DeleteFileA(p)) return ERR_WRITE;
    join(p, dir, "xinput1_4.dll.off"); if (exists(p) && isOurDll(p)) DeleteFileA(p);
    const char *files[] = {"default.txt", "default.txt.bak", "wasdmod.log", "wasdmod.old.log", "wasdmod-record.flag", "Key Layout Editor.html", "wasdmod.ini", "wasdmod.ini.bak", "wasd-mod.ini", "wasd-mod.ini.bak", "wasd-mod.log"};
    for (unsigned i = 0; i < sizeof(files) / sizeof(*files); i++) { join(p, dir, files[i]); DeleteFileA(p); }
    if (removeLayout) { findLayouts(dir, 0, deleteFile); findFiles(dir, "wasd-mod*.txt", 0, deleteFile); join(p, dir, "author.txt.bak"); DeleteFileA(p); }
    return OK;
}

enum { NOT_INSTALLED, INSTALLED_LATEST, INSTALLED_OLDER, OTHER_DLL, TURNED_OFF };
static int installState(const char *dir) {
    char dll[PATHLEN], off[PATHLEN]; join(dll, dir, "xinput1_4.dll"); join(off, dir, "xinput1_4.dll.off");
    if (!exists(dll)) return exists(off) && isOurDll(off) ? TURNED_OFF : NOT_INSTALLED;
    if (!isOurDll(dll)) return OTHER_DLL;
    return sameAs(dll, payloadDll, sizeof(payloadDll)) ? INSTALLED_LATEST : INSTALLED_OLDER;
}
// The settings file the mod uses: the newest saved layout when it's newer than default.txt.
static void activeSettings(const char *dir, char *out) {
    char ini[PATHLEN], txt[PATHLEN]; join(ini, dir, "default.txt");
    scpy(out, PATHLEN, findLayouts(dir, txt, 0) && newer(txt, ini) ? txt : ini);
}
// Turning the mod off renames it to xinput1_4.dll.off: the game starts without it
// and loads the system's XInput, and the settings and layouts stay for next time.
// Works with the game running too (it applies the next time the game starts).
static int turnOn(const char *dir, int on) {
    char dll[PATHLEN], off[PATHLEN]; join(dll, dir, "xinput1_4.dll"); join(off, dir, "xinput1_4.dll.off");
    if (on) return exists(dll) ? OK : isOurDll(off) && MoveFileExA(off, dll, 0) ? OK : ERR_WRITE;
    if (!exists(dll) || !isOurDll(dll)) return OK;
    return MoveFileExA(dll, off, 1 /*MOVEFILE_REPLACE_EXISTING*/) ? OK : ERR_WRITE;
}
// Switches the layout: 0 Default, 1 Recommended, 2 your newest wasdmod*.txt.
static int useLayout(const char *dir, int which) {
    char p[PATHLEN];
    if (which == 0) return putLayout(dir, "default.txt", payloadIni, sizeof(payloadIni)) ? OK : ERR_WRITE;
    if (which == 1) return putLayout(dir, "author.txt", payloadAuthor, sizeof(payloadAuthor)) ? OK : ERR_WRITE;
    if (!findFiles(dir, "wasdmod*.txt", p, 0)) return ERR_WRITE;
    touch(p);
    return OK;
}

